P.QBANK = ["Was zeigt mir dieser Abschnitt darüber, wer Gott ist?","Welche selbstbezogene alte Natur deckt dieser Abschnitt in mir auf?","Was würde ich tun, wenn ich Jesus in dieser Situation regieren ließe?","Welches Vorbild gibt mir Jesus hier?","Welchen Schritt möchte der Heilige Geist mich heute durch dieses Wort gehen lassen?","Warum sind die Menschen hier gescheitert? War die Wurzel Stolz oder Angst?","Wie hilft mir dieser Abschnitt, Wu Ji (Selbstentäußerung) einzuüben?","In welcher Beziehung kann ich diesen Abschnitt umsetzen?","Was hat dieser Abschnitt mit der Bitte im Vaterunser „Dein Reich komme“ zu tun?","Gib mir ein Bild aus dem Alltag, damit ich den Kern dieses Abschnitts verstehe."];
P.QAUD = {"seeker":["Was hat dieser Abschnitt mit meinem Leben heute zu tun?","Ich praktiziere den christlichen Glauben noch nicht. Was könnten diese Worte für mich bedeuten?","Gibt es Gott wirklich? Welche Gründe gibt es zu glauben?","Warum sagt die Bibel, dass jeder Mensch Jesus braucht?","Ich stehe sehr unter Druck. Welche konkrete Hilfe kann mir die Bibel geben?","Was bedeutet hier das Wort „Sünde“? Betrifft es mich?","Christen reden ständig von „Gnade“. Was ist das, einfach erklärt?","Wenn ich mehr erfahren möchte, wo fange ich an?"],"teen":["Was hat dieser Abschnitt mit meinem Alltag zu tun – Schule, Freunde, Handy?","Wenn dieser Abschnitt eine Nachricht von Gott nur für mich wäre, was würde er sagen?","Alle machen es. Ist es komisch, nicht mitzumachen? Was sagt die Bibel dazu?","Kannst du mir diesen Abschnitt mit einem Videospiel oder einem Film erklären?","Was ist an diesem Abschnitt überraschend oder wenig bekannt?","Der Druck vor den Prüfungen ist riesig. Welche Kraft gibt mir dieser Abschnitt?","Es fällt mir schwer, jemandem zu vergeben. Wie hilft mir dieser Abschnitt?","Sieht Gott mich wirklich? Warum bin ich der Liebe wert?"],"kid":["Worum geht es in dieser Geschichte? Kannst du sie mir erzählen?","Was hat Gott in dieser Geschichte getan?","Hat Jesus mich lieb? Woher weiß ich das?","Wer ist in dieser Geschichte am mutigsten? Warum?","Wie kann ich so sein wie die Menschen in dieser Geschichte?","Bring mir einen kurzen Vers bei, den ich auswendig lernen kann.","Ich habe mich mit meinem besten Freund gestritten. Was würde Jesus tun?","Kannst du mir ein ganz kleines Gebet beibringen?"]};
P.AUD2 = {"elder":{"q":["Was sagt dieser Abschnitt in ganz einfachen Worten?","Welchen Trost schenkt dieser Abschnitt älteren Menschen?","Mein Körper wird schwächer. Wie sorgt Gott für mich?","Ich fühle mich oft einsam. Was gibt mir dieser Abschnitt?","Wie kann ich meinen Glauben an meine Kinder und Enkel weitergeben?","Manches kann ich nicht loslassen. Wie lehrt mich dieser Abschnitt, es dem Herrn anzuvertrauen?","Ich bin schon alt. Was kann ich noch für Gott tun?","Schreib mir bitte ein kurzes Gebet, das ich dem Herrn vortragen kann."],"fu":["Gesundheit","Einsamkeit","Familie","Anvertrauen","Hoffnung","Gebet"],"rw":["Du hast das ganze Buch {nm} zu Ende gelesen!","Tag für Tag bist du bis hierher gekommen. Gott denkt an diese Treue, und sie ist ein Vorbild für die Jüngeren."],"res":["Keine Sorge, wir gehen es in Ruhe an. Beim nochmaligen Lesen wird es klarer werden.","Sehr gut! Du erinnerst dich an vieles aus diesem Kapitel.","Wunderbar! Das Wort Gottes lebt in deinem Herzen."]},"single_parent":{"q":["Ich trage die Verantwortung für die Familie allein. Welchen Trost gibt mir dieser Abschnitt?","Ich bin völlig erschöpft und habe das Gefühl, meinen Kindern nicht genug zu geben. Wie sieht Gott mich?","Wie sorgt Gott für Waisen und Witwen, und was bedeutet das für mich?","Das Geld ist sehr knapp. Was gibt mir dieser Abschnitt?","Mein Kind gibt Widerworte und hat sehr starke Gefühle. Was soll ich tun?","Ich weiß nicht, wie ich meinem Kind sagen soll, dass Papa (oder Mama) nicht bei uns ist.","Ich fühle mich sehr einsam. Wie kann ich die Gemeinde oder meine Geschwister im Glauben um Hilfe bitten?","Schreib mir bitte ein kurzes Gebet, das ich in fünf Minuten beten kann."],"fu":["Erschöpfung","Kind","Geld","Um Hilfe bitten","Hoffnung","Gebet"],"rw":["Du hast das ganze Buch {nm} zu Ende gelesen!","Es ist nicht leicht, weiter in der Bibel zu lesen, wenn man eine Familie allein trägt. Gott sieht jeden deiner Schritte, und er ist bei dir."],"res":["Keine Sorge, du hast dir so viel Mühe gegeben. Lies es noch einmal, wenn du Zeit hast.","Sehr gut! Du behältst so viel, trotz deiner vollen Tage.","Wunderbar! Das Wort Gottes trägt dich."]},"single":{"q":["Was sagt mir dieser Abschnitt als alleinstehendem Menschen?","Ich fühle mich einsam. Was gibt mir dieser Abschnitt?","Wer bin ich in Christus, und was bin ich wert?","Wie vertraue ich Gott, während ich warte?","Welche Weisheit schenkt die Bibel für Beziehungen?","Wie können Zeit und Kraft eines alleinstehenden Menschen für Gott eingesetzt werden?","Wie baue ich gute Beziehungen in der Gemeinde und zu meinen Freunden auf?","Schreib mir bitte ein kurzes Gebet für einen alleinstehenden Menschen."],"fu":["Einsamkeit","Identität","Warten","Beziehungen","Lebenssinn","Gebet"],"rw":["Du hast das ganze Buch {nm} zu Ende gelesen!","Du bist allein weitergegangen, und vor Gott sind deine Tage erfüllt und geliebt."],"res":["Keine Sorge, wir gehen es in Ruhe an. Beim nochmaligen Lesen wird es klarer werden.","Sehr gut! Du hast das Wesentliche dieses Kapitels erfasst.","Ausgezeichnet! Du bleibst dran, und das Wort Gottes schlägt Wurzeln in dir."]},"parent":{"q":["Woran erinnert mich dieser Abschnitt als Elternteil?","Mein Kind hört nicht auf mich und hat sehr starke Gefühle. Wie soll ich reagieren?","Wie bringe ich Konsequenz und Gnade zusammen?","Wie spreche ich gut mit einem jugendlichen Kind?","Ich werde oft laut gegenüber meinem Kind und habe danach ein schlechtes Gewissen. Was kann ich tun?","Wie führe ich mein Kind dahin, Gott kennenzulernen, statt nur in die Kirche zu gehen?","Mein Partner und ich sind uns in der Erziehung nicht einig. Was sagt dieser Abschnitt dazu?","Schreib mir bitte ein kurzes Segensgebet für mein Kind."],"fu":["Gespräch","Konsequenz","Gewissen","Partnerschaft","Glaube","Gebet"],"rw":["Du hast das ganze Buch {nm} zu Ende gelesen!","Mitten im Trubel der Kindererziehung täglich in der Schrift zu lesen, ist das schönste Vorbild, das du ihnen geben kannst."],"res":["Keine Sorge, wir gehen es in Ruhe an. Lies es noch einmal, wenn du Gelegenheit hast.","Sehr gut! Du hast das Wesentliche dieses Kapitels erfasst.","Wunderbar! Das Wort Gottes schlägt Wurzeln in eurem Zuhause."]},"couple":{"q":["Was sagt dieser Abschnitt uns als Paar?","Nach jedem Streit gehen wir auf Abstand. Wie kann einer von uns den ersten Schritt zur Versöhnung tun?","Wie kann ich sagen, was mich bewegt, damit mein Partner mir zuhört?","Mein Partner hat mich verletzt. Muss ich wirklich vergeben?","Wir sind uns über Geld und Haushaltsaufgaben uneins. Was tun?","Wie können wir gemeinsam beten und uns als Paar Gott nähern?","Wir haben uns im Alltagstrubel auseinandergelebt. Wie finden wir wieder zueinander?","Schreib uns bitte ein kurzes Segensgebet für unsere Ehe."],"fu":["Gespräch","Vergebung","Nähe","Ein Herz","Gemeinsam lesen","Gebet"],"rw":["Ihr habt gemeinsam das ganze Buch {nm} zu Ende gelesen!","Ein Paar, das sich gemeinsam dem Wort Gottes nähert, steht auf festem Grund."],"res":["Keine Sorge, wir gehen es in Ruhe an. Lest es an einem Abend gemeinsam noch einmal.","Sehr gut! Ihr beide habt das Wesentliche dieses Kapitels erfasst.","Wunderbar! Das Wort Gottes schlägt Wurzeln in eurer Ehe."]},"pastor":{"q":["Was sagt mir dieser Abschnitt im Dienst für den Herrn?","Hilf mir, eine Predigtgliederung und einen Einstieg für diesen Abschnitt zu finden.","Ich stehe kurz vor dem Ausbrennen. Welchen Trost schenkt mir dieser Abschnitt?","Wie gehe ich mit Kritik und Missverständnissen in der Gemeinde um?","Was sagt dieser Abschnitt dazu, ein Team einmütig zu leiten?","Wie pflege ich meine persönliche Beziehung zu Gott mitten in einem so vollen Dienst?","Wie sorge ich für die Schwachen, Verletzten und für die, die sich von der Gemeinde entfernt haben?","Schreib mir bitte ein kurzes Fürbittgebet für die Gemeinde und meine Mitarbeitenden."],"fu":["Predigt","Seelsorge","Team","Ruhe","Geistlicher Kampf","Fürbitte"],"rw":["Du hast das ganze Buch {nm} zu Ende gelesen!","Mitten im vollen Dienst nahe beim Wort Gottes zu bleiben, ist die tiefste Wurzel jedes Hirtendienstes."],"res":["Keine Sorge, wir gehen es in Ruhe an. Lies es noch einmal, wenn du Gelegenheit hast.","Sehr gut! Du hast das Wesentliche dieses Kapitels erfasst.","Wunderbar! Das Wort Gottes nährt zuerst den Hirten und fließt dann zur Herde."]}};
